{"source":"function Unresolved_b6b55f25(uint256 arg0) public {
        if (0x04 + (msg.data.length - 0x04) - 0x04 >= 0x10) {
            require(uint8(uint256(store_f) / 0x010000000000000000000000000000000000000000) == 0, CustomError_9e87fac8());
            require(arg0 >= uint256(store_c), CustomError_3261c792());
            uint256 fee = (arg0 * uint256(unresolved_ddca3f43)) / 10000;
            uint256 net = arg0 - fee;
            unresolved_70a08231[msg.sender] += net;
            var_c += net;
            emit Event_ddf252ad(address(0), msg.sender, net);
